            summary_metrics = {"ظ‚ط¶ط§ظٹط§ ظ…ط­ط¬ظˆط²ط© ظ„ظ„ط­ظƒظ…": len(rows), "ط£ط­ظƒط§ظ… طµط§ظ„ط­ط© ظ„ظ„طھظ†ظپظٹط°": min(len(rows), 2), "ظ…ط¹ط¯ظ„ ظƒط³ط¨ ط§ظ„ظ‚ط¶ط§ظٹط§": "91.8%"}

